   670→    /**
   671→     * @description Reorder work items by updating Order__c values and handling re-parenting
   672→     * @param draggedItemId The ID of the work item being dragged
   673→     * @param targetItemId The ID of the work item being dropped on
   674→     * @param draggedParentId The parent ID of the dragged work item (null for root items)
   675→     * @param targetParentId The parent ID of the target work item (null for root items). When equal to targetItemId, makes dragged item a child of target.
   676→     */
   677→    @AuraEnabled
   678→    public static void moveWorkItem(Id draggedItemId, Id targetItemId) {
   679→        if (draggedItemId == null || targetItemId == null) {
   680→            throw new AppException('Dragged and target work item IDs are required');
   681→        }
   682→
   683→        if (draggedItemId == targetItemId) {
   684→            return; // No reorder needed
   685→        }
   686→
   687→        try {
   688→            // First, get the project ID from the dragged item
   689→            Map<Id, Work_Item__c> itemsByIds = new Map<Id, Work_Item__c>(
   690→                [
   691→                    SELECT Id, Project__c, Parent_Work_Item__c, Work_Item_Template__c
   692→                    FROM Work_Item__c
   693→                    WHERE Id IN :new Set<Id>{ draggedItemId, targetItemId }
   694→                    WITH USER_MODE
   695→                ]
   696→            );
   697→
   698→            Work_Item__c draggedItem = itemsByIds.get(draggedItemId);
   699→            Work_Item__c targetItem = itemsByIds.get(targetItemId);
   700→
   701→            // Use targetParentId to determine if reparenting is needed
   702→            if (draggedItem.Parent_Work_Item__c == targetItem.Parent_Work_Item__c) {
   703→                // Same parent, just reorder
   704→                reorderWorkItem(draggedItem, targetItem);
   705→            } else {
   706→                // Different parent, reparent
   707→                reparentWorkItem(draggedItem, targetItem);
   708→            }
   709→        } catch (Exception e) {
   710→            System.debug(LoggingLevel.ERROR, 'Error reordering work items: ' + e.getMessage());
   711→            throw new AppException('Error reordering work items: ' + e.getMessage());
   712→        }
   713→    }
