   715→    private static void reorderWorkItem(Work_Item__c draggedItem, Work_Item__c targetItem) {
   716→        // Query all siblings (items with same parent)
   717→        List<Work_Item__c> siblings = getSiblings(draggedItem.Parent_Work_Item__c ?? draggedItem.Project__c);
   718→
   719→        if (siblings.isEmpty()) {
   720→            throw new AppException('No work items found to reorder');
   721→        }
   722→
   723→        Integer draggedIndex = getIndex(siblings, draggedItem.Id);
   724→        Integer targetIndex = getIndex(siblings, targetItem.Id);
   725→
   726→        // Reorder the list
   727→        Work_Item__c movedItem = siblings.remove(draggedIndex);
   728→
   729→        insertItem(siblings, targetIndex, movedItem);
   730→
   731→        // Reassign Order values
   732→        orderWorkItems(siblings);
   733→    }
   734→
   735→    private static void reparentWorkItem(Work_Item__c draggedItem, Work_Item__c targetItem) {
   736→        Id newParentId = null;
   737→        Boolean asParent = false;
   738→
   739→        // Strategy 1: Assume drop was onto parent (targetItem becomes the new parent)
   740→        // Check if targetItem's template allows draggedItem's template as a child
   741→        Integer allowedAsChildCount = [
   742→            SELECT COUNT()
   743→            FROM Allowed_Child_Type__c
   744→            WHERE Parent_Work_Item_Template__c = :targetItem.Work_Item_Template__c AND Child_Work_Item_Template__c = :draggedItem.Work_Item_Template__c
   745→            WITH USER_MODE
   746→        ];
   747→
   748→        if (allowedAsChildCount > 0) {
   749→            // Valid: targetItem can be the parent
   750→            newParentId = targetItem.Id;
   751→            asParent = true;
   752→        } else {
   753→            // Strategy 2: Try as sibling (targetItem's parent becomes the new parent)
   754→            if (targetItem.Parent_Work_Item__c != null) {
   755→                // targetItem has a parent - check if that parent allows draggedItem
   756→                Work_Item__c targetParent = [
   757→                    SELECT Id, Work_Item_Template__c
   758→                    FROM Work_Item__c
   759→                    WHERE Id = :targetItem.Parent_Work_Item__c
   760→                    WITH USER_MODE
   761→                    LIMIT 1
   762→                ];
   763→
   764→                Integer allowedAsSiblingCount = [
   765→                    SELECT COUNT()
   766→                    FROM Allowed_Child_Type__c
   767→                    WHERE Parent_Work_Item_Template__c = :targetParent.Work_Item_Template__c AND Child_Work_Item_Template__c = :draggedItem.Work_Item_Template__c
   768→                    WITH USER_MODE
   769→                ];
   770→
   771→                if (allowedAsSiblingCount > 0) {
   772→                    // Valid: targetItem's parent can be the parent (making them siblings)
   773→                    newParentId = targetItem.Parent_Work_Item__c;
   774→                    asParent = false;
   775→                } else {
   776→                    throw new AppException('Cannot move work item: neither the target nor its parent allows this work item type as a child.');
   777→                }
   778→            } else {
   779→                // targetItem is a root item - check if project template allows draggedItem at root
   780→                Project__c project = [
   781→                    SELECT Id, Project_Template__c
   782→                    FROM Project__c
   783→                    WHERE Id = :draggedItem.Project__c
   784→                    WITH USER_MODE
   785→                    LIMIT 1
   786→                ];
   787→
   788→                Integer allowedAtRootCount = [
   789→                    SELECT COUNT()
   790→                    FROM Project_Template_Work_Item_Type__c
   791→                    WHERE Project_Template__c = :project.Project_Template__c AND Work_Item_Template__c = :draggedItem.Work_Item_Template__c
   792→                    WITH USER_MODE
   793→                ];
   794→
   795→                if (allowedAtRootCount > 0) {
   796→                    // Valid: draggedItem can be at root level (sibling to targetItem)
   797→                    newParentId = null;
   798→                    asParent = false;
   799→                } else {
   800→                    throw new AppException('Cannot move work item: target does not allow this work item type as a child, and project template does not allow it at root level.');
   801→                }
   802→            }
   803→        }
   804→
   805→        // Query all siblings (items with same parent)
   806→        List<Work_Item__c> oldSiblings = getSiblings(draggedItem.Parent_Work_Item__c ?? draggedItem.Project__c);
   807→        List<Work_Item__c> newSiblings;
   808→
   809→        if (asParent) {
   810→            // Dropping onto parent - get children of targetItem
   811→            newSiblings = getSiblings(targetItem.Id);
   812→        } else {
   813→            // Dropping as sibling - get siblings of targetItem
   814→            newSiblings = getSiblings(targetItem.Parent_Work_Item__c ?? targetItem.Project__c);
   815→        }
   816→
   817→        // Find indices
   818→        Integer draggedIndex = getIndex(oldSiblings, draggedItem.Id);
   819→        Work_Item__c movedItem = oldSiblings.remove(draggedIndex);
   820→
   821→        Integer targetIndex;
   822→
   823→        if (asParent) {
   824→            // Dropping onto parent - add to end of children
   825→            targetIndex = newSiblings.size();
   826→        } else {
   827→            // Dropping as sibling - insert at target position
   828→            targetIndex = getIndex(newSiblings, targetItem.Id);
   829→        }
   830→
   831→        movedItem.Parent_Work_Item__c = newParentId;
   832→        insertItem(newSiblings, targetIndex, movedItem);
   833→
   834→        orderWorkItems(oldSiblings);
   835→        orderWorkItems(newSiblings);
   836→    }
