   838→    private static List<Work_Item__c> getSiblings(Id parentId) {
   839→        if (parentId.getSobjectType().equals(Project__c.getSObjectType())) {
   840→            return [
   841→                SELECT Id, Order__c, Parent_Work_Item__c
   842→                FROM Work_Item__c
   843→                WHERE Parent_Work_Item__c = NULL AND Project__c = :parentId
   844→                WITH USER_MODE
   845→                ORDER BY Order__c ASC NULLS LAST, CreatedDate ASC
   846→            ];
   847→        } else if (parentId.getSobjectType().equals(Work_Item__c.getSObjectType())) {
   848→            return [
   849→                SELECT Id, Order__c, Parent_Work_Item__c
   850→                FROM Work_Item__c
   851→                WHERE Parent_Work_Item__c = :parentId
   852→                WITH USER_MODE
   853→                ORDER BY Order__c ASC NULLS LAST, CreatedDate ASC
   854→            ];
   855→        }
   856→
   857→        return new List<Work_Item__c>();
   858→    }
   859→
   860→    private static void insertItem(List<Work_Item__c> newSiblings, Integer targetIndex, Work_Item__c movedItem) {
   861→        if (newSiblings.size() <= targetIndex) {
   862→            newSiblings.add(movedItem);
   863→        } else {
   864→            newSiblings.add(targetIndex, movedItem);
   865→        }
   866→    }
