   868→    private static Integer getIndex(List<Work_Item__c> records, Id itemId) {
   869→        Integer index = -1;
   870→        for (Integer i = 0; i < records.size(); i++) {
   871→            if (records[i].Id == itemId) {
   872→                index = i;
   873→            }
   874→        }
   875→
   876→        if (index == -1) {
   877→            List<String> foundIds = new List<String>();
   878→
   879→            for (Work_Item__c wi : records) {
   880→                foundIds.add(wi.Id);
   881→            }
   882→
   883→            throw new AppException('Could not find work item ' + itemId + ' in sibling list. Found ' + records.size() + ' siblings: ' + String.join(foundIds, ', '));
   884→        }
   885→
   886→        return index;
   887→    }
