   889→    private static void orderWorkItems(List<Work_Item__c> siblings) {
   890→        List<Work_Item__c> itemsToUpdate = new List<Work_Item__c>();
   891→        Decimal orderValue = 0;
   892→
   893→        for (Work_Item__c item : siblings) {
   894→            item.Order__c = orderValue++;
   895→            itemsToUpdate.add(item);
   896→        }
   897→
   898→        // Update with FLS enforcement
   899→        SObjectAccessDecision decision = Security.stripInaccessible(AccessType.UPDATABLE, itemsToUpdate);
   900→
   901→        update decision.getRecords();
   902→    }
