  1056→    /**
  1057→     * Recursively builds hierarchy by fetching children for parent Work Items
  1058→     *
  1059→     * @param wrappers List of parent wrappers to populate with children
  1060→     * @param parentIds Set of parent IDs to query children for
  1061→     * @param currentDepth Current depth in the hierarchy
  1062→     * @param maxDepth Maximum depth to traverse
  1063→     */
  1064→    private static void buildHierarchy(List<WorkItemWrapper> wrappers, Set<Id> parentIds, Integer currentDepth, Integer maxDepth) {
  1065→        if (currentDepth > maxDepth || parentIds.isEmpty()) {
  1066→            return;
  1067→        }
  1068→
  1069→        // Get all children for the current level
  1070→        Map<Id, List<Work_Item__c>> parentToChildrenMap = WorkItemService.getChildrenForParents(parentIds);
  1071→
  1072→        if (parentToChildrenMap.isEmpty()) {
  1073→            return;
