/**
 * @description Controller class for Work Item Lightning Web Components
 * Provides @AuraEnabled methods for querying and manipulating Work Items
 *
 * @group Controllers
 *
 * @date 2025-10-06
 */
public with sharing class WorkItemController {
    /**
     * @description Wrapper class for Project data with Work Items
     */
    public class ProjectDataWrapper {
        @AuraEnabled
        public Id projectId { get; set; }
        @AuraEnabled
        public Date projectStartDate { get; set; }
        @AuraEnabled
        public Date projectDueDate { get; set; }
        @AuraEnabled
        public List<WorkItemWrapper> workItems { get; set; }
        @AuraEnabled
        public List<PicklistOption> statusOptions { get; set; }

        private Set<String> statusNames { get; set; }

        public ProjectDataWrapper(Id projectId, Date startDate, Date dueDate, List<WorkItemWrapper> items) {
            this.projectId = projectId;
            this.projectStartDate = startDate;
            this.projectDueDate = dueDate;
            this.workItems = items;

            this.statusNames = new Set<String>();
            this.getStatusOptions(items);

            this.statusOptions = new List<PicklistOption>{ new PicklistOption('All Statuses', '') };
            for (String statusName : statusNames) {
                this.statusOptions.add(new PicklistOption(statusName, statusName));
            }
        }

        private void getStatusOptions(List<WorkItemWrapper> items) {
            for (WorkItemWrapper item : items) {
                if (item.workflow != null) {
                    for (StatusOption option : item.workflow) {
                        statusNames.add(option.name);
                    }
                }

                if (item.children != null) {
                    this.getStatusOptions(item.children);
                }
            }
        }
    }

    /**
     * @description Wrapper class for Work Item Assignments
     */
    public class WorkItemAssignmentWrapper {
        @AuraEnabled
        public Id id { get; set; }
        @AuraEnabled
        public String resourceName { get; set; }
        @AuraEnabled
        public String role { get; set; }
        @AuraEnabled
        public Boolean isPrimary { get; set; }
        @AuraEnabled
        public Id projectRoleId { get; set; }
        @AuraEnabled
        public String projectRoleName { get; set; }
    }

    /**
     * @description Wrapper class for Work Items with hierarchical children
     */
    public class WorkItemWrapper {
        @AuraEnabled
        public Id id { get; set; }
        @AuraEnabled
        public String name { get; set; }
        @AuraEnabled
        public String status { get; set; }
        @AuraEnabled
        public Date startDate { get; set; }
        @AuraEnabled
        public Date dueDate { get; set; }
        @AuraEnabled
        public Decimal estimatedHours { get; set; }
        @AuraEnabled
        public Decimal actualHours { get; set; }
        @AuraEnabled
        public String description { get; set; }
        @AuraEnabled
        public String nextSteps { get; set; }
        @AuraEnabled
        public Id projectId { get; set; }
        @AuraEnabled
        public Id parentWorkItemId { get; set; }
        @AuraEnabled
        public Id templateId { get; set; }
        @AuraEnabled
        public String templateName { get; set; }
        @AuraEnabled
        public Integer depth { get; set; }
        @AuraEnabled
        public Decimal progress { get; set; }
        @AuraEnabled
        public Boolean isAtRisk { get; set; }
        @AuraEnabled
        public String atRiskDetails { get; set; }
        @AuraEnabled
        public Boolean isBlocked { get; set; }
        @AuraEnabled
        public String blockedDetails { get; set; }
        @AuraEnabled
        public Id blockerWorkItemId { get; set; }
        @AuraEnabled
        public String blockerWorkItemName { get; set; }
        @AuraEnabled
        public List<WorkItemWrapper> children { get; set; }
        @AuraEnabled
        public Datetime createdDate { get; set; }
        @AuraEnabled
        public Datetime lastModifiedDate { get; set; }
        @AuraEnabled
        public Id ownerId { get; set; }
        @AuraEnabled
        public String ownerName { get; set; }
        @AuraEnabled
        public List<WorkItemAssignmentWrapper> assignments { get; set; }
        @AuraEnabled
        public String timelineValidation { get; set; }
        @AuraEnabled
        public Boolean hasTimelineConflict { get; set; }
        @AuraEnabled
        public String timelineConflictMessage { get; set; }
        @AuraEnabled
        public Date parentStartDate { get; set; }
        @AuraEnabled
        public Date parentDueDate { get; set; }
        @AuraEnabled
        public List<String> highlights { get; set; }
        @AuraEnabled
        public String headerColor { get; set; }
        @AuraEnabled
        public List<StatusOption> workflow { get; set; }
        @AuraEnabled
        public Boolean hasTransitions { get; set; }

        /**
         * @description Constructor from Work_Item__c record
         */
        public WorkItemWrapper(Work_Item__c workItem, Integer currentDepth) {
            this.id = workItem.Id;
            this.name = workItem.Work_Item_Name__c;
            this.status = workItem.Status__c;
            this.startDate = workItem.Start_Date__c;
            this.dueDate = workItem.Due_Date__c;
            this.estimatedHours = workItem.Estimated_Hours__c;
            this.actualHours = workItem.Actual_Hours__c;
            this.description = workItem.Summary__c;
            this.nextSteps = workItem.Next_Steps__c;
            this.projectId = workItem.Project__c;
            this.parentWorkItemId = workItem.Parent_Work_Item__c;
            this.templateId = workItem.Work_Item_Template__c;
            this.templateName = workItem.Work_Item_Template__r?.Name;
            this.depth = currentDepth;
            this.progress = WorkItemService.calculateProgress(workItem.Estimated_Hours__c, workItem.Actual_Hours__c);
            this.isAtRisk = workItem.At_Risk__c != null ? workItem.At_Risk__c : false;
            this.atRiskDetails = workItem.At_Risk_Details__c;
            this.isBlocked = workItem.Blocked__c != null ? workItem.Blocked__c : false;
            this.blockedDetails = workItem.Blocked_Details__c;
            this.blockerWorkItemId = workItem.Blocker_Work_Item__c;
            this.blockerWorkItemName = workItem.Blocker_Work_Item__r?.Work_Item_Name__c;
            this.children = new List<WorkItemWrapper>();
            this.createdDate = workItem.CreatedDate;
            this.lastModifiedDate = workItem.LastModifiedDate;
            this.ownerId = workItem.OwnerId;
            this.ownerName = workItem.Owner.Name;

            // Header Color from template
            this.headerColor = workItem.Work_Item_Template__r?.Header_Color__c;

            // Timeline Validation logic
            this.timelineValidation = workItem.Work_Item_Template__r?.Timeline_Validation__c;
            this.hasTimelineConflict = false;
            this.timelineConflictMessage = null;

            // Workflow from template
            if (workItem.Work_Item_Template__r?.Workflow__c != null) {
                this.workflow = (List<StatusOption>) JSON.deserializeStrict(workItem.Work_Item_Template__r.Workflow__c, List<StatusOption>.class);

                this.hasTransitions = false;
                for (StatusOption option : this.workflow) {
                    if (option.transitions != null && !option.transitions.isEmpty()) {
                        this.hasTransitions = true;
                        break;
                    }
                }
            }

            // Check if this work item has a parent and timeline validation is enabled
            if (workItem.Parent_Work_Item__c != null && this.timelineValidation == 'Warning' && workItem.Start_Date__c != null && workItem.Due_Date__c != null) {
                this.parentStartDate = workItem.Parent_Work_Item__r?.Start_Date__c;
                this.parentDueDate = workItem.Parent_Work_Item__r?.Due_Date__c;

                // Check if child dates are outside parent range
                if (this.parentStartDate != null && this.parentDueDate != null) {
                    if (workItem.Start_Date__c < this.parentStartDate || workItem.Due_Date__c > this.parentDueDate) {
                        this.hasTimelineConflict = true;
                        this.timelineConflictMessage =
                            'This work item\'s timeline extends outside the parent work item\'s date range (' +
                            this.parentStartDate.format() +
                            ' - ' +
                            this.parentDueDate.format() +
                            ')';
                    }
                }
            }

            // Build highlights array based on various alert conditions
            this.highlights = new List<String>();
            if (this.isAtRisk) {
                this.highlights.add('at-risk');
            }
            if (this.isBlocked) {
                this.highlights.add('blocked');
            }
            if (this.hasTimelineConflict) {
                this.highlights.add('timeline-conflict');
            }

            this.assignments = new List<WorkItemAssignmentWrapper>();

            // Populate assignments from Work Item Assignments
            if (workItem.Work_Item_Assignments__r != null) {
                for (Work_Item_Assignment__c assignment : workItem.Work_Item_Assignments__r) {
                    WorkItemAssignmentWrapper assignmentWrapper = new WorkItemAssignmentWrapper();
                    assignmentWrapper.id = assignment.Id;
                    assignmentWrapper.role = assignment.Role_on_Work_Item__c;
                    assignmentWrapper.isPrimary = assignment.Is_Primary__c;
                    assignmentWrapper.projectRoleId = assignment.Project_Role__c;
                    assignmentWrapper.projectRoleName = assignment.Project_Role__r?.Name;

                    // Get resource name from either User or Contact
                    if (assignment.Resource_Assignment__r?.Resource_User__c != null) {
                        assignmentWrapper.resourceName = assignment.Resource_Assignment__r.Resource_User__r?.Name;
                    } else if (assignment.Resource_Assignment__r?.Resource_Contact__c != null) {
                        assignmentWrapper.resourceName = assignment.Resource_Assignment__r.Resource_Contact__r?.Name;
                    }

                    this.assignments.add(assignmentWrapper);
                }
            }
        }
    }

    /**
     * @description Simple wrapper for work item picklist options
     */
    public class StatusOption {
        @AuraEnabled
        public String name { get; set; }
        @AuraEnabled
        public String variant { get; set; }
        @AuraEnabled
        public List<String> transitions { get; set; }

        public StatusOption(String name, String variant, List<String> transitions) {
            this.name = name;
            this.variant = variant;
            this.transitions = transitions;
        }
    }

    /**
     * Gets all root-level Work Items for a Project with their children
     *
     * @param projectId The Project ID to query Work Items for
     * @param maxDepth Maximum hierarchy depth to retrieve (default 3)
     *
     * @return ProjectDataWrapper with project dates and work items
     */
    @AuraEnabled(Cacheable=true)
    public static ProjectDataWrapper getWorkItemsForProject(Id projectId, Integer maxDepth) {
        try {
            if (maxDepth == null || maxDepth < 1) {
                maxDepth = 3;
            }

            // Get project dates
            Project__c project = [
                SELECT Id, Start_Date__c, End_Date__c
                FROM Project__c
                WHERE Id = :projectId
                WITH USER_MODE
                LIMIT 1
            ];

            List<Work_Item__c> rootItems = WorkItemService.getWorkItemsForProject(projectId, maxDepth);

            // Convert to wrappers
            List<WorkItemWrapper> rootWrappers = new List<WorkItemWrapper>();
            for (Work_Item__c item : rootItems) {
                rootWrappers.add(new WorkItemWrapper(item, 0));
            }

            // Build hierarchy if depth > 0
            if (maxDepth > 0 && !rootWrappers.isEmpty()) {
                Set<Id> rootIds = new Set<Id>();
                for (WorkItemWrapper wrapper : rootWrappers) {
                    rootIds.add(wrapper.id);
                }
                buildHierarchy(rootWrappers, rootIds, 1, maxDepth);
            }

            return new ProjectDataWrapper(project.Id, project.Start_Date__c, project.End_Date__c, rootWrappers);
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error in getWorkItemsForProject: ' + e.getMessage());
            throw new AppException('Error retrieving Work Items: ' + e.getMessage());
        }
    }

    /**
     * @description Gets a specific Work Item with all its children
     * @param workItemId The Work Item ID to retrieve
     * @param maxDepth Maximum hierarchy depth to retrieve (default 3)
     *
     * @return WorkItemWrapper object with hierarchical children
     */
    @AuraEnabled(Cacheable=true)
    public static WorkItemWrapper getWorkItemWithChildren(Id workItemId, Integer maxDepth) {
        try {
            if (maxDepth == null) {
                maxDepth = 3;
            }

            Work_Item__c workItem = WorkItemService.getWorkItemWithChildren(workItemId, maxDepth);
            WorkItemWrapper wrapper = new WorkItemWrapper(workItem, 0);

            // Build hierarchy if depth > 0
            if (maxDepth > 0) {
                buildHierarchy(new List<WorkItemWrapper>{ wrapper }, new Set<Id>{ wrapper.id }, 1, maxDepth);
            }

            return wrapper;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error in getWorkItemWithChildren: ' + e.getMessage());
            throw new AppException('Error retrieving Work Item: ' + e.getMessage());
        }
    }

    /**
     * @description Refreshes a specific Work Item (non-cacheable for fresh data)
     * @param workItemId The Work Item ID to retrieve
     *
     * @return WorkItemWrapper object with fresh data
     */
    @AuraEnabled(Cacheable=false)
    public static WorkItemWrapper refreshWorkItem(Id workItemId) {
        try {
            Work_Item__c workItem = WorkItemService.getWorkItemWithChildren(workItemId, 0);
            WorkItemWrapper wrapper = new WorkItemWrapper(workItem, 0);
            return wrapper;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error in refreshWorkItem: ' + e.getMessage());
            throw new AppException('Error refreshing Work Item: ' + e.getMessage());
        }
    }

    /**
     * @description Updates a Work Item with the provided field values
     * @param workItemId The Work Item ID to update
     * @param fields Map of field API names to values
     */
    @AuraEnabled
    public static void updateWorkItem(Id workItemId, Map<String, Object> fields) {
        try {
            WorkItemService.updateWorkItem(workItemId, fields);
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error in updateWorkItem: ' + e.getMessage());
            throw new AppException('Error updating Work Item: ' + e.getMessage());
        }
    }

    /**
     * @description Get field history for a Work Item
     * @param workItemId The ID of the Work Item
     *
     * @return List of field history records
     */
    @AuraEnabled(Cacheable=false)
    public static List<Work_Item__History> getWorkItemHistory(Id workItemId) {
        if (workItemId == null) {
            throw new AppException('Work Item ID is required');
        }

        try {
            return [
                SELECT Id, Field, OldValue, NewValue, CreatedDate, CreatedBy.Name, CreatedById
                FROM Work_Item__History
                WHERE ParentId = :workItemId
                ORDER BY CreatedDate DESC
                LIMIT 500
            ];
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error retrieving Work Item history: ' + e.getMessage());
            throw new AppException('Error retrieving Work Item history: ' + e.getMessage());
        }
    }

    /**
     * @description Simple wrapper for picklist options
     */
    public class PicklistOption {
        @AuraEnabled
        public String label { get; set; }
        @AuraEnabled
        public String value { get; set; }

        public PicklistOption(String label, String value) {
            this.label = label;
            this.value = value;
        }
    }

    /**
     * @description Gets all work items for a project as picklist options
     *
     * @param projectId The Project ID
     *
     * @return List of work item options
     */
    @AuraEnabled(Cacheable=true)
    public static List<PicklistOption> getWorkItemOptionsForProject(Id projectId) {
        try {
            List<PicklistOption> options = new List<PicklistOption>();

            List<Work_Item__c> workItems = [
                SELECT Id, Work_Item_Name__c, Order__c
                FROM Work_Item__c
                WHERE Project__c = :projectId
                WITH USER_MODE
                ORDER BY Order__c ASC NULLS LAST, Work_Item_Name__c ASC
            ];

            for (Work_Item__c wi : workItems) {
                options.add(new PicklistOption(wi.Work_Item_Name__c, wi.Id));
            }

            return options;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error retrieving work item options: ' + e.getMessage());
            throw new AppException('Error retrieving work item options: ' + e.getMessage());
        }
    }

    /**
     * @description Get count of allowed child work item types for a template
     * @param workItemTemplateId The Work Item Template ID
     *
     * @return Count of allowed child types
     */
    @AuraEnabled(Cacheable=true)
    public static Integer getAllowedChildTypeCount(Id workItemTemplateId) {
        if (workItemTemplateId == null) {
            return 0;
        }

        try {
            return [
                SELECT COUNT()
                FROM Allowed_Child_Type__c
                WHERE Parent_Work_Item_Template__c = :workItemTemplateId AND Child_Work_Item_Template__r.Active__c = TRUE
                WITH USER_MODE
            ];
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error retrieving allowed child type count: ' + e.getMessage());
            return 0;
        }
    }

    /**
     * @description Wrapper class for available resources
     */
    public class AvailableResourceWrapper {
        @AuraEnabled
        public Id id { get; set; }
        @AuraEnabled
        public String resourceName { get; set; }
        @AuraEnabled
        public String resourceType { get; set; }
        @AuraEnabled
        public Id userId { get; set; }
        @AuraEnabled
        public Id contactId { get; set; }
        @AuraEnabled
        public Id defaultRoleId { get; set; }
    }

    /**
     * @description Get Role picklist values from Work Item Assignment object
     * @return List of picklist entry labels
     */
    @AuraEnabled(Cacheable=true)
    public static List<String> getRolePicklistValues() {
        try {
            List<String> picklistValues = new List<String>();

            Schema.DescribeFieldResult fieldResult = Work_Item_Assignment__c.Role_on_Work_Item__c.getDescribe();
            List<Schema.PicklistEntry> picklistEntries = fieldResult.getPicklistValues();

            for (Schema.PicklistEntry entry : picklistEntries) {
                if (entry.isActive()) {
                    picklistValues.add(entry.getLabel());
                }
            }

            return picklistValues;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error retrieving role picklist values: ' + e.getMessage());
            throw new AppException('Error retrieving role picklist values: ' + e.getMessage());
        }
    }

    /**
     * @description Get Project Roles for a project
     * @param projectId The Project ID
     *
     * @return List of Project Role records with Id and Name
     */
    @AuraEnabled(Cacheable=true)
    public static List<Project_Role__c> getProjectRoles(Id projectId) {
        if (projectId == null) {
            throw new AppException('Project ID is required');
        }

        try {
            return [
                SELECT Id, Name
                FROM Project_Role__c
                WHERE Project__c = :projectId
                WITH USER_MODE
                ORDER BY Name ASC
            ];
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error retrieving project roles: ' + e.getMessage());
            throw new AppException('Error retrieving project roles: ' + e.getMessage());
        }
    }

    /**
     * @description Get available resources for a project that can be assigned to work items
     * @param projectId The Project ID
     *
     * @return List of available resource assignments
     */
    @AuraEnabled(Cacheable=true)
    public static List<AvailableResourceWrapper> getAvailableResources(Id projectId) {
        if (projectId == null) {
            throw new AppException('Project ID is required');
        }

        try {
            List<AvailableResourceWrapper> resources = new List<AvailableResourceWrapper>();

            // Query all resource assignments for the project
            List<Resource_Assignment__c> resourceAssignments = [
                SELECT Id, Resource_User__c, Resource_User__r.Name, Resource_Contact__c, Resource_Contact__r.Name, Resource_Classification__c, Default_Role__c
                FROM Resource_Assignment__c
                WHERE Project__c = :projectId
                WITH USER_MODE
                ORDER BY Resource_User__r.Name ASC NULLS LAST, Resource_Contact__r.Name ASC NULLS LAST
            ];

            for (Resource_Assignment__c ra : resourceAssignments) {
                AvailableResourceWrapper wrapper = new AvailableResourceWrapper();
                wrapper.id = ra.Id;
                wrapper.resourceType = ra.Resource_Classification__c;
                wrapper.defaultRoleId = ra.Default_Role__c;

                if (ra.Resource_User__c != null) {
                    wrapper.resourceName = ra.Resource_User__r.Name;
                    wrapper.userId = ra.Resource_User__c;
                } else if (ra.Resource_Contact__c != null) {
                    wrapper.resourceName = ra.Resource_Contact__r.Name;
                    wrapper.contactId = ra.Resource_Contact__c;
                }

                resources.add(wrapper);
            }

            return resources;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error retrieving available resources: ' + e.getMessage());
            throw new AppException('Error retrieving available resources: ' + e.getMessage());
        }
    }

    /**
     * @description Add a new work item assignment
     * @param workItemId The Work Item ID
     * @param resourceAssignmentId The Resource Assignment ID
     * @param role Role on the work item
     * @param isPrimary Whether this is the primary resource
     * @param projectRoleId The Project Role ID (optional)
     */
    @AuraEnabled
    public static void addWorkItemAssignment(Id workItemId, Id resourceAssignmentId, String role, Boolean isPrimary, Id projectRoleId) {
        if (workItemId == null) {
            throw new AppException('Work Item ID is required');
        }

        if (resourceAssignmentId == null) {
            throw new AppException('Resource Assignment ID is required');
        }

        try {
            Work_Item_Assignment__c assignment = new Work_Item_Assignment__c(
                Work_Item__c = workItemId,
                Resource_Assignment__c = resourceAssignmentId,
                Role_on_Work_Item__c = role,
                Is_Primary__c = isPrimary != null ? isPrimary : false,
                Project_Role__c = projectRoleId,
                Assignment_Date__c = Date.today()
            );

            // Use stripInaccessible to enforce FLS
            SObjectAccessDecision decision = Security.stripInaccessible(AccessType.CREATABLE, new List<Work_Item_Assignment__c>{ assignment });

            insert decision.getRecords();
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error adding work item assignment: ' + e.getMessage());
            throw new AppException('Error adding work item assignment: ' + e.getMessage());
        }
    }

    /**
     * @description Remove a work item assignment
     * @param assignmentId The Work Item Assignment ID to remove
     */
    @AuraEnabled
    public static void removeWorkItemAssignment(Id assignmentId) {
        if (assignmentId == null) {
            throw new AppException('Assignment ID is required');
        }

        try {
            List<Work_Item_Assignment__c> assignments = [
                SELECT Id
                FROM Work_Item_Assignment__c
                WHERE Id = :assignmentId
                WITH USER_MODE
                LIMIT 1
            ];

            if (assignments.isEmpty()) {
                throw new AppException('Assignment not found or access denied');
            }

            delete as user assignments;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error removing work item assignment: ' + e.getMessage());
            throw new AppException('Error removing work item assignment: ' + e.getMessage());
        }
    }

    /**
     * @description Reorder work items by updating Order__c values and handling re-parenting
     * @param draggedItemId The ID of the work item being dragged
     * @param targetItemId The ID of the work item being dropped on
     * @param draggedParentId The parent ID of the dragged work item (null for root items)
     * @param targetParentId The parent ID of the target work item (null for root items). When equal to targetItemId, makes dragged item a child of target.
     */
    @AuraEnabled
    public static void moveWorkItem(Id draggedItemId, Id targetItemId) {
        if (draggedItemId == null || targetItemId == null) {
            throw new AppException('Dragged and target work item IDs are required');
        }

        if (draggedItemId == targetItemId) {
            return; // No reorder needed
        }

        try {
            // First, get the project ID from the dragged item
            Map<Id, Work_Item__c> itemsByIds = new Map<Id, Work_Item__c>(
                [
                    SELECT Id, Project__c, Parent_Work_Item__c, Work_Item_Template__c
                    FROM Work_Item__c
                    WHERE Id IN :new Set<Id>{ draggedItemId, targetItemId }
                    WITH USER_MODE
                ]
            );

            Work_Item__c draggedItem = itemsByIds.get(draggedItemId);
            Work_Item__c targetItem = itemsByIds.get(targetItemId);

            // Use targetParentId to determine if reparenting is needed
            if (draggedItem.Parent_Work_Item__c == targetItem.Parent_Work_Item__c) {
                // Same parent, just reorder
                reorderWorkItem(draggedItem, targetItem);
            } else {
                // Different parent, reparent
                reparentWorkItem(draggedItem, targetItem);
            }
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error reordering work items: ' + e.getMessage());
            throw new AppException('Error reordering work items: ' + e.getMessage());
        }
    }

    private static void reorderWorkItem(Work_Item__c draggedItem, Work_Item__c targetItem) {
        // Query all siblings (items with same parent)
        List<Work_Item__c> siblings = getSiblings(draggedItem.Parent_Work_Item__c ?? draggedItem.Project__c);

        if (siblings.isEmpty()) {
            throw new AppException('No work items found to reorder');
        }

        Integer draggedIndex = getIndex(siblings, draggedItem.Id);
        Integer targetIndex = getIndex(siblings, targetItem.Id);

        // Reorder the list
        Work_Item__c movedItem = siblings.remove(draggedIndex);

        insertItem(siblings, targetIndex, movedItem);

        // Reassign Order values
        orderWorkItems(siblings);
    }

    private static void reparentWorkItem(Work_Item__c draggedItem, Work_Item__c targetItem) {
        Id newParentId = null;
        Boolean asParent = false;

        // Strategy 1: Assume drop was onto parent (targetItem becomes the new parent)
        // Check if targetItem's template allows draggedItem's template as a child
        Integer allowedAsChildCount = [
            SELECT COUNT()
            FROM Allowed_Child_Type__c
            WHERE Parent_Work_Item_Template__c = :targetItem.Work_Item_Template__c AND Child_Work_Item_Template__c = :draggedItem.Work_Item_Template__c
            WITH USER_MODE
        ];

        if (allowedAsChildCount > 0) {
            // Valid: targetItem can be the parent
            newParentId = targetItem.Id;
            asParent = true;
        } else {
            // Strategy 2: Try as sibling (targetItem's parent becomes the new parent)
            if (targetItem.Parent_Work_Item__c != null) {
                // targetItem has a parent - check if that parent allows draggedItem
                Work_Item__c targetParent = [
                    SELECT Id, Work_Item_Template__c
                    FROM Work_Item__c
                    WHERE Id = :targetItem.Parent_Work_Item__c
                    WITH USER_MODE
                    LIMIT 1
                ];

                Integer allowedAsSiblingCount = [
                    SELECT COUNT()
                    FROM Allowed_Child_Type__c
                    WHERE Parent_Work_Item_Template__c = :targetParent.Work_Item_Template__c AND Child_Work_Item_Template__c = :draggedItem.Work_Item_Template__c
                    WITH USER_MODE
                ];

                if (allowedAsSiblingCount > 0) {
                    // Valid: targetItem's parent can be the parent (making them siblings)
                    newParentId = targetItem.Parent_Work_Item__c;
                    asParent = false;
                } else {
                    throw new AppException('Cannot move work item: neither the target nor its parent allows this work item type as a child.');
                }
            } else {
                // targetItem is a root item - check if project template allows draggedItem at root
                Project__c project = [
                    SELECT Id, Project_Template__c
                    FROM Project__c
                    WHERE Id = :draggedItem.Project__c
                    WITH USER_MODE
                    LIMIT 1
                ];

                Integer allowedAtRootCount = [
                    SELECT COUNT()
                    FROM Project_Template_Work_Item_Type__c
                    WHERE Project_Template__c = :project.Project_Template__c AND Work_Item_Template__c = :draggedItem.Work_Item_Template__c
                    WITH USER_MODE
                ];

                if (allowedAtRootCount > 0) {
                    // Valid: draggedItem can be at root level (sibling to targetItem)
                    newParentId = null;
                    asParent = false;
                } else {
                    throw new AppException('Cannot move work item: target does not allow this work item type as a child, and project template does not allow it at root level.');
                }
            }
        }

        // Query all siblings (items with same parent)
        List<Work_Item__c> oldSiblings = getSiblings(draggedItem.Parent_Work_Item__c ?? draggedItem.Project__c);
        List<Work_Item__c> newSiblings;

        if (asParent) {
            // Dropping onto parent - get children of targetItem
            newSiblings = getSiblings(targetItem.Id);
        } else {
            // Dropping as sibling - get siblings of targetItem
            newSiblings = getSiblings(targetItem.Parent_Work_Item__c ?? targetItem.Project__c);
        }

        // Find indices
        Integer draggedIndex = getIndex(oldSiblings, draggedItem.Id);
        Work_Item__c movedItem = oldSiblings.remove(draggedIndex);

        Integer targetIndex;

        if (asParent) {
            // Dropping onto parent - add to end of children
            targetIndex = newSiblings.size();
        } else {
            // Dropping as sibling - insert at target position
            targetIndex = getIndex(newSiblings, targetItem.Id);
        }

        movedItem.Parent_Work_Item__c = newParentId;
        insertItem(newSiblings, targetIndex, movedItem);

        orderWorkItems(oldSiblings);
        orderWorkItems(newSiblings);
    }

    private static List<Work_Item__c> getSiblings(Id parentId) {
        if (parentId.getSobjectType().equals(Project__c.getSObjectType())) {
            return [
                SELECT Id, Order__c, Parent_Work_Item__c
                FROM Work_Item__c
                WHERE Parent_Work_Item__c = NULL AND Project__c = :parentId
                WITH USER_MODE
                ORDER BY Order__c ASC NULLS LAST, CreatedDate ASC
            ];
        } else if (parentId.getSobjectType().equals(Work_Item__c.getSObjectType())) {
            return [
                SELECT Id, Order__c, Parent_Work_Item__c
                FROM Work_Item__c
                WHERE Parent_Work_Item__c = :parentId
                WITH USER_MODE
                ORDER BY Order__c ASC NULLS LAST, CreatedDate ASC
            ];
        }

        return new List<Work_Item__c>();
    }

    private static void insertItem(List<Work_Item__c> newSiblings, Integer targetIndex, Work_Item__c movedItem) {
        if (newSiblings.size() <= targetIndex) {
            newSiblings.add(movedItem);
        } else {
            newSiblings.add(targetIndex, movedItem);
        }
    }

    private static Integer getIndex(List<Work_Item__c> records, Id itemId) {
        Integer index = -1;
        for (Integer i = 0; i < records.size(); i++) {
            if (records[i].Id == itemId) {
                index = i;
            }
        }

        if (index == -1) {
            List<String> foundIds = new List<String>();

            for (Work_Item__c wi : records) {
                foundIds.add(wi.Id);
            }

            throw new AppException('Could not find work item ' + itemId + ' in sibling list. Found ' + records.size() + ' siblings: ' + String.join(foundIds, ', '));
        }

        return index;
    }

    private static void orderWorkItems(List<Work_Item__c> siblings) {
        List<Work_Item__c> itemsToUpdate = new List<Work_Item__c>();
        Decimal orderValue = 0;

        for (Work_Item__c item : siblings) {
            item.Order__c = orderValue++;
            itemsToUpdate.add(item);
        }

        // Update with FLS enforcement
        SObjectAccessDecision decision = Security.stripInaccessible(AccessType.UPDATABLE, itemsToUpdate);

        update decision.getRecords();
    }

    /**
     * @description Update the owner (primary resource) of a work item
     * @param workItemId The Work Item ID
     * @param newOwnerId The new Owner User ID
     */
    @AuraEnabled
    public static void updateWorkItemOwner(Id workItemId, Id newOwnerId) {
        if (workItemId == null) {
            throw new AppException('Work Item ID is required');
        }

        if (newOwnerId == null) {
            throw new AppException('Owner ID is required');
        }

        try {
            Work_Item__c workItem = new Work_Item__c(Id = workItemId, OwnerId = newOwnerId);

            // Use stripInaccessible to enforce FLS
            SObjectAccessDecision decision = Security.stripInaccessible(AccessType.UPDATABLE, new List<Work_Item__c>{ workItem });

            update decision.getRecords();
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error updating work item owner: ' + e.getMessage());
            throw new AppException('Error updating work item owner: ' + e.getMessage());
        }
    }

