    /**
     * @description Get time entries for a work item and all its descendants
     * @param workItemId The ID of the Work Item
     *
     * @return List of time entry records including entries from all child work items
     */
    @AuraEnabled(Cacheable=false)
    public static List<TimeEntryWrapper> getTimeEntriesForWorkItem(Id workItemId) {
        if (workItemId == null) {
            throw new AppException('Work Item ID is required');
        }

        try {
            List<TimeEntryWrapper> wrappers = new List<TimeEntryWrapper>();

            // Get all descendant work item IDs
            Set<Id> allWorkItemIds = getAllDescendantWorkItemIds(workItemId);

            // Query time entries for this work item and all descendants
            List<Time_Entry__c> timeEntries = [
                SELECT
                    Id,
                    Name,
                    Date__c,
                    Hours__c,
                    Description__c,
                    Work_Item__c,
                    Work_Item__r.Work_Item_Name__c,
                    Resource_Assignment__c,
                    Resource_Assignment__r.Resource_Name__c,
                    CreatedDate,
                    CreatedBy.Name
                FROM Time_Entry__c
                WHERE Work_Item__c IN :allWorkItemIds
                WITH USER_MODE
                ORDER BY Date__c DESC, CreatedDate DESC
                LIMIT 500
            ];

            for (Time_Entry__c entry : timeEntries) {
                TimeEntryWrapper wrapper = new TimeEntryWrapper();
                wrapper.id = entry.Id;
                wrapper.timeEntryNumber = entry.Name;
                wrapper.entryDate = entry.Date__c;
                wrapper.hours = entry.Hours__c;
                wrapper.description = entry.Description__c;
                wrapper.workItemId = entry.Work_Item__c;
                wrapper.workItemName = entry.Work_Item__r != null ? entry.Work_Item__r.Work_Item_Name__c : null;
                wrapper.resourceName = entry.Resource_Assignment__r != null ? entry.Resource_Assignment__r.Resource_Name__c : null;
                wrapper.resourceAssignmentId = entry.Resource_Assignment__c;
                wrapper.createdDate = entry.CreatedDate;
                wrapper.createdByName = entry.CreatedBy.Name;
                wrappers.add(wrapper);
            }

            return wrappers;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error retrieving time entries: ' + e.getMessage());
            throw new AppException('Error retrieving time entries: ' + e.getMessage());
        }
    }

    /**
     * @description Recursively get all descendant work item IDs
     * @param workItemId The root work item ID
     *
     * @return Set of all work item IDs including the root and all descendants
     */
    private static Set<Id> getAllDescendantWorkItemIds(Id workItemId) {
        Set<Id> allIds = new Set<Id>{ workItemId };
        Set<Id> currentLevelIds = new Set<Id>{ workItemId };

        // Recursively fetch children up to a reasonable depth (prevent infinite loops)
        for (Integer i = 0; i < 10; i++) {
            Set<Id> nextLevelIds = new Set<Id>();

            for (Work_Item__c child : [
                SELECT Id
                FROM Work_Item__c
                WHERE Parent_Work_Item__c IN :currentLevelIds
                WITH USER_MODE
            ]) {
                nextLevelIds.add(child.Id);
                allIds.add(child.Id);
            }

            if (nextLevelIds.isEmpty()) {
                break;
            }

            currentLevelIds = nextLevelIds;
        }

        return allIds;
    }

    /**
     * Recursively builds hierarchy by fetching children for parent Work Items
     *
     * @param wrappers List of parent wrappers to populate with children
     * @param parentIds Set of parent IDs to query children for
     * @param currentDepth Current depth in the hierarchy
     * @param maxDepth Maximum depth to traverse
     */
    private static void buildHierarchy(List<WorkItemWrapper> wrappers, Set<Id> parentIds, Integer currentDepth, Integer maxDepth) {
        if (currentDepth > maxDepth || parentIds.isEmpty()) {
            return;
        }

        // Get all children for the current level
        Map<Id, List<Work_Item__c>> parentToChildrenMap = WorkItemService.getChildrenForParents(parentIds);

        if (parentToChildrenMap.isEmpty()) {
            return;
        }

        // Map wrappers by ID for quick lookup
        Map<Id, WorkItemWrapper> wrapperMap = new Map<Id, WorkItemWrapper>();
        for (WorkItemWrapper wrapper : wrappers) {
            wrapperMap.put(wrapper.id, wrapper);
        }

        // Attach children to their parents
        Set<Id> nextLevelIds = new Set<Id>();
        List<WorkItemWrapper> nextLevelWrappers = new List<WorkItemWrapper>();

        for (Id parentId : parentToChildrenMap.keySet()) {
            WorkItemWrapper parentWrapper = wrapperMap.get(parentId);
            if (parentWrapper != null) {
                for (Work_Item__c child : parentToChildrenMap.get(parentId)) {
                    WorkItemWrapper childWrapper = new WorkItemWrapper(child, currentDepth);
                    parentWrapper.children.add(childWrapper);
                    nextLevelIds.add(child.Id);
                    nextLevelWrappers.add(childWrapper);
                }
            }
        }

        // Recursively process next level
        if (!nextLevelWrappers.isEmpty() && currentDepth < maxDepth) {
            buildHierarchy(nextLevelWrappers, nextLevelIds, currentDepth + 1, maxDepth);
        }
    }
}

