/**
 * Created by nick on 2025-11-21.
 */

import { api } from 'lwc';
import BaseComponent from 'c/baseComponent';

export default class WorkItemDetails extends BaseComponent {
    @api recordId; // Project or Work Item ID
    @api objectApiName; // Object type (cgpm__Project__c or cgpm__Work_Item__c)

    workItems = []; // Loaded Work Items
    record = {}; // Resolved Work Item

    connectedCallback() {
        // DEBUG: Check if we actually have context
        console.log('Details Component Init:', {
            id: this.recordId,
            obj: this.objectApiName
        });
    }

    /**
     * Handle messages from Lightning Message Service
     */
    handleMessage(message) {
        super.handleMessage(message);

        switch (message.action) {
            case 'activateWorkItem':
                this.record = this.workItems.find((item) => item.id === message.workItemId) || {};
                break;

            default:
            // Do nothing for other messages
        }
    }

    /**
     * Handle wired data from either method
     */
    handleWorkItemsLoad(event) {
        const { workItems } = event.detail;
        this.workItems = workItems || [];
    }
}

