   568→    /**
   569→     * Primary highlight type (for determining border color priority)
   570→     * Priority: blocked (red) > at-risk (yellow) > timeline-conflict (orange)
   571→     */
   572→    get primaryHighlight() {
   573→        if (!this.workItem.highlights || this.workItem.highlights.length === 0) {
