public with sharing class WorkItemCreateController {
    /**
     * Get available Work Item Templates for a given project
     * @param projectId - The project ID
     * @param parentWorkItemId - Optional parent work item ID (for filtering child templates)
     */
    @AuraEnabled(Cacheable=true)
    public static List<TemplateOption> getWorkItemTemplates(Id projectId, Id parentWorkItemId) {
        List<TemplateOption> options = new List<TemplateOption>();

        try {
            // If parent work item is specified, filter by allowed child templates
            if (parentWorkItemId != null) {
                // Get parent work item's template
                List<Work_Item__c> parentItems = [
                    SELECT Work_Item_Template__c
                    FROM Work_Item__c
                    WHERE Id = :parentWorkItemId
                    WITH USER_MODE
                    LIMIT 1
                ];

                if (!parentItems.isEmpty() && parentItems[0].Work_Item_Template__c != null) {
                    Id parentTemplateId = parentItems[0].Work_Item_Template__c;

                    // Get allowed child templates for this parent template
                    List<Allowed_Child_Type__c> allowedChildren = [
                        SELECT Child_Work_Item_Template__c, Child_Work_Item_Template__r.Name, Order__c
                        FROM Allowed_Child_Type__c
                        WHERE Parent_Work_Item_Template__c = :parentTemplateId AND Child_Work_Item_Template__r.Active__c = TRUE
                        WITH USER_MODE
                        ORDER BY Order__c NULLS LAST, Child_Work_Item_Template__r.Name
                    ];

                    for (Allowed_Child_Type__c allowedChild : allowedChildren) {
                        options.add(new TemplateOption(allowedChild.Child_Work_Item_Template__c, allowedChild.Child_Work_Item_Template__r.Name, null));
                    }
                } else {
                    // Parent has no template, allow all active templates
                    return getAllActiveTemplates();
                }
            } else {
                // No parent specified, check if project has template restrictions
                return getTemplatesForProject(projectId);
            }

            return options;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error in getWorkItemTemplates: ' + e.getMessage());
            throw new AuraHandledException('Error retrieving work item templates: ' + e.getMessage());
        }
    }

    /**
     * Get templates allowed for a project (based on project template configuration)
     */
    private static List<TemplateOption> getTemplatesForProject(Id projectId) {
        List<TemplateOption> options = new List<TemplateOption>();

        // Get the project's template
        List<Project__c> projects = [
            SELECT Project_Template__c
            FROM Project__c
            WHERE Id = :projectId
            WITH USER_MODE
            LIMIT 1
        ];

        // If project has a template, get allowed work item templates
        if (!projects.isEmpty() && projects[0].Project_Template__c != null) {
            Id projectTemplateId = projects[0].Project_Template__c;

            // Get allowed work item templates for this project template
            List<Project_Template_Work_Item_Type__c> allowedTypes = [
                SELECT Work_Item_Template__c, Work_Item_Template__r.Name, Default_Order__c
                FROM Project_Template_Work_Item_Type__c
                WHERE Project_Template__c = :projectTemplateId AND Work_Item_Template__r.Active__c = TRUE
                WITH USER_MODE
                ORDER BY Default_Order__c NULLS LAST, Work_Item_Template__r.Name
            ];

            for (Project_Template_Work_Item_Type__c allowedType : allowedTypes) {
                options.add(new TemplateOption(allowedType.Work_Item_Template__c, allowedType.Work_Item_Template__r.Name, null));
            }

            // If no allowed types configured, fall back to all active templates
            if (options.isEmpty()) {
                return getAllActiveTemplates();
            }
        } else {
            // No project template, return all active templates
            return getAllActiveTemplates();
        }

        return options;
    }

    /**
     * Helper method to get all active templates
     */
